function flattenAirtable(items) {
  const out = [];
  for (const item of items || []) {
    const records = item && item.json && Array.isArray(item.json.records) ? item.json.records : [];
    for (const record of records) {
      out.push(Object.assign({ record_id: record.id }, record.fields || {}));
    }
  }
  return out;
}

function configMap(rows) {
  const map = {};
  for (const row of rows || []) {
    if (row.key) map[row.key] = row.value;
  }
  return map;
}

function chunkRecords(list, size) {
  const out = [];
  for (let i = 0; i < list.length; i += size) out.push(list.slice(i, i + size));
  return out;
}

function opsToArray(value) {
  if (!value) return [];
  return Array.isArray(value) ? value : [value];
}

function opsText(value) {
  return value === null || value === undefined ? "" : String(value).trim();
}

function opsBool(value) {
  if (value === true) return true;
  if (value === false || value === null || value === undefined) return false;
  return ["true", "1", "yes", "y"].includes(opsText(value).toLowerCase());
}

function opsConfig(configRows) {
  const config = {};
  for (const row of opsToArray(configRows)) {
    const key = opsText(row.key);
    if (key) config[key] = opsText(row.value);
  }
  return config;
}

function opsDatePartsInTimezone(date, timeZone) {
  const parts = new Intl.DateTimeFormat("en-CA", {
    timeZone,
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
  }).formatToParts(date);
  const out = {};
  for (const part of parts) out[part.type] = part.value;
  return { year: Number(out.year), month: Number(out.month), day: Number(out.day) };
}

function opsTodayIso(timeZone) {
  const p = opsDatePartsInTimezone(new Date(), timeZone || "America/New_York");
  return `${p.year}-${String(p.month).padStart(2, "0")}-${String(p.day).padStart(2, "0")}`;
}

function opsIsoDate(value, timeZone) {
  const text = opsText(value);
  if (/^\d{4}-\d{2}-\d{2}$/.test(text)) return text;
  const date = new Date(text);
  if (Number.isNaN(date.getTime())) return "";
  const p = opsDatePartsInTimezone(date, timeZone || "America/New_York");
  return `${p.year}-${String(p.month).padStart(2, "0")}-${String(p.day).padStart(2, "0")}`;
}

function opsDaysBetween(startIso, endIso) {
  if (!startIso || !endIso) return null;
  const [sy, sm, sd] = String(startIso).split("-").map(Number);
  const [ey, em, ed] = String(endIso).split("-").map(Number);
  if (![sy, sm, sd, ey, em, ed].every(Number.isFinite)) return null;
  const start = Date.UTC(sy, sm - 1, sd, 12);
  const end = Date.UTC(ey, em - 1, ed, 12);
  return Math.round((end - start) / 86400000);
}

function opsCohortFor(days, hasLeaseEnd) {
  if (!hasLeaseEnd) return "NONE";
  if (days === null || days === undefined) return "NONE";
  if (days < 0) return "EXPIRED";
  if (days >= 105 && days <= 135) return "120";
  if (days >= 75 && days <= 104) return "90";
  if (days >= 45 && days <= 74) return "60";
  if (days >= 20 && days <= 44) return "30";
  return "NONE";
}

function isMeaningfulReplyLog(log) {
  const eventType = opsText(log.event_type).toUpperCase();
  const intent = opsText(log.intent).toUpperCase();
  if (!opsText(log.lease_id)) return false;
  if (intent === "NO_SIGNAL" || eventType === "NO_SIGNAL") return false;
  if (["REPLY_CLASSIFIED", "CLASSIFY_FAILED", "UNMATCHED_REPLY"].includes(eventType)) return true;
  if (opsBool(log.requires_human) && opsText(log.reply_text)) return true;
  return false;
}

function shouldEscalateNonResponse(lease, meaningfulReplyLeaseIds, baseDate, thresholdDays, timeZone) {
  const status = opsText(lease.status).toUpperCase();
  if (status !== "SENT") return false;
  if (meaningfulReplyLeaseIds.has(opsText(lease.lease_id))) return false;
  const sentDate = opsIsoDate(lease.sent_at, timeZone);
  if (!sentDate) return false;
  const daysSinceSent = opsDaysBetween(sentDate, baseDate);
  return daysSinceSent !== null && daysSinceSent > thresholdDays;
}

function cleanLeaseForTable(row) {
  return {
    lease_id: opsText(row.lease_id),
    tenant_name: opsText(row.tenant_name),
    tenant_first_name: opsText(row.tenant_first_name),
    unit: opsText(row.unit),
    email: opsText(row.email),
    email_valid: opsBool(row.email_valid),
    move_in_date: row.move_in_date || null,
    lease_end_date: row.lease_end_date || null,
    days_to_expiry: row.days_to_expiry === null || row.days_to_expiry === undefined || row.days_to_expiry === "" ? null : Number(row.days_to_expiry),
    cohort: opsText(row.cohort),
    tenure_months: row.tenure_months === null || row.tenure_months === undefined || row.tenure_months === "" ? null : Number(row.tenure_months),
    status: opsText(row.status) || "PENDING",
    draft_subject: opsText(row.draft_subject),
    draft_body: opsText(row.draft_body),
    ref_token: opsText(row.ref_token),
    sent_at: row.sent_at || null,
    opted_out: opsBool(row.opted_out),
    ingest_notes: opsText(row.ingest_notes),
  };
}

function prepareSweepUpdates(leases, outreachLog, config, requestBody = {}) {
  const timeZone = opsText(config.timezone) || "America/New_York";
  const baseDate = opsText(requestBody.base_date) || opsTodayIso(timeZone);
  const thresholdDays = Number(requestBody.escalate_after_days || config.escalate_after_days || 15);
  const meaningfulReplyLeaseIds = new Set(opsToArray(outreachLog).filter(isMeaningfulReplyLog).map((log) => opsText(log.lease_id)));
  const updates = [];
  const seenLeaseIds = new Set();
  let escalatedCount = 0;
  let currentAtRiskCount = 0;
  let currentStayingCount = 0;
  let currentEscalateCount = 0;

  for (const rawLease of opsToArray(leases)) {
    const lease = cleanLeaseForTable(rawLease);
    if (!lease.lease_id || seenLeaseIds.has(lease.lease_id)) continue;
    seenLeaseIds.add(lease.lease_id);

    const leaseEnd = opsIsoDate(lease.lease_end_date, timeZone);
    const days = leaseEnd ? opsDaysBetween(baseDate, leaseEnd) : null;
    const cohort = opsCohortFor(days, Boolean(leaseEnd));
    let status = lease.status || "PENDING";
    const wasStatus = status;

    if (shouldEscalateNonResponse(lease, meaningfulReplyLeaseIds, baseDate, thresholdDays, timeZone)) {
      status = "ESCALATE";
      escalatedCount += 1;
    }

    if (status === "AT_RISK") currentAtRiskCount += 1;
    if (status === "STAYING") currentStayingCount += 1;
    if (status === "ESCALATE") currentEscalateCount += 1;

    if (lease.days_to_expiry !== days || lease.cohort !== cohort || wasStatus !== status) {
      updates.push({
        ...lease,
        lease_end_date: leaseEnd || null,
        days_to_expiry: days,
        cohort,
        status,
      });
    }
  }

  const summary = {
    ok: true,
    action: "daily_sweep",
    base_date: baseDate,
    total_rows: seenLeaseIds.size,
    updated_count: updates.length,
    recomputed_count: seenLeaseIds.size,
    escalated_count: escalatedCount,
    current_escalate_count: currentEscalateCount,
    at_risk_count: currentAtRiskCount,
    staying_count: currentStayingCount,
    threshold_days: thresholdDays,
    digest_suppressed: opsBool(requestBody.suppress_digest),
    board_url: "http://localhost:5678/webhook/board",
  };

  return { updates, summary };
}

function buildSweepDigest(summary, config) {
  const company = opsText(config.company_name) || "Renewal retention demo";
  return `${company} sweep ${summary.base_date}: ${summary.recomputed_count} rows checked, ${summary.escalated_count} new escalations, ${summary.at_risk_count} at risk, ${summary.staying_count} staying.`;
}

function resetLeaseState(row) {
  return cleanLeaseForTable({
    ...row,
    status: "PENDING",
    draft_subject: "",
    draft_body: "",
    ref_token: "",
    sent_at: null,
    opted_out: false,
  });
}

function buildResetRows(rosterCsv, config) {
  if (typeof normalizeRoster !== "function") {
    throw new Error("Stage 3 normalizeRoster helper is required for reset.");
  }
  const timeZone = opsText(config.timezone) || "America/New_York";
  const normalized = normalizeRoster(rosterCsv, {
    timezone: timeZone,
    baseDate: opsText(config.demo_base_date) || "2026-08-04",
    demoRecipientEmail: opsText(config.demo_recipient_email),
    boardUrl: "http://localhost:5678/webhook/board",
    uploadedAt: new Date().toISOString(),
    existingRows: [],
  });
  const rows = normalized.rows.map(resetLeaseState);
  return {
    rows,
    summary: {
      ok: true,
      action: "reset_demo",
      loaded_count: rows.length,
      flagged_count: normalized.summary.flagged_count,
      cohort_counts: normalized.summary.cohort_counts,
      cleared_outreach_log: true,
      cleared_leases: true,
      gmail_processed_clear_requested: false,
      gmail_processed_clear_count: 0,
      board_url: "http://localhost:5678/webhook/board",
    },
  };
}

function buildErrorAlertText(input) {
  const execution = input.execution || {};
  const workflow = input.workflow || {};
  const error = execution.error || input.error || {};
  const workflowName = opsText(workflow.name || input.workflow_name) || "Unknown workflow";
  const nodeName = opsText(execution.lastNodeExecuted || input.node_name) || "Unknown node";
  const message = opsText(error.message || input.message) || "Unknown error";
  const executionUrl = opsText(execution.url || input.execution_url);
  return [
    `n8n workflow error - ${workflowName}`,
    `Node: ${nodeName}`,
    `Error: ${message}`,
    `Time: ${new Date().toISOString()}`,
    executionUrl ? `Execution: ${executionUrl}` : "",
  ].filter(Boolean).join("\n");
}
/**
 * Demo scoreboard maths for the v2 Metrics table and the Telegram digest.
 *
 * The headline number is turnover exposure: the money at risk in the residents
 * currently flagged AT_RISK or ESCALATE, valued at config.avg_turnover_cost.
 * Exposure recovered is the same figure for issues a manager has closed.
 *
 * These are demo-grade proxies, not a financial model. The POC does not claim a
 * resolved issue guarantees a renewal - only that the exposure was surfaced and
 * acted on. Say that out loud when presenting the number.
 *
 * This file is inlined into n8n Code nodes at import time.
 */

const AT_RISK_STATUSES = new Set(["AT_RISK", "ESCALATE"]);

function txt(value) {
  return value == null ? "" : String(value).trim();
}

function num(value, fallback = 0) {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : fallback;
}

function round1(value) {
  return Math.round(value * 10) / 10;
}

/**
 * @param {Array} leases  every lease row
 * @param {Array} logRows every outreach log row
 * @param {object} config config key/value map
 */
function computeMetrics(leases, logRows, config = {}) {
  const rows = leases || [];
  const log = logRows || [];
  const turnoverCost = num(config.avg_turnover_cost, 3900);

  const residentsInWindow = rows.filter((lease) => txt(lease.cohort) === "90").length;

  const checkInsSent = log.filter((row) => txt(row.event_type) === "SENT").length;
  const repliesReceived = log.filter((row) => txt(row.event_type) === "REPLY_RECEIVED").length;

  const issuesOpen = rows.filter((lease) => txt(lease.issue_status) === "OPEN");
  const issuesResolved = rows.filter((lease) => txt(lease.issue_status) === "RESOLVED");
  const issuesFound = issuesOpen.length + issuesResolved.length;

  const atRisk = rows.filter((lease) => AT_RISK_STATUSES.has(txt(lease.status).toUpperCase()));
  const staying = rows.filter((lease) => txt(lease.status).toUpperCase() === "STAYING");

  const resolutionDays = issuesResolved
    .map((lease) => num(lease.days_to_resolve, null))
    .filter((value) => value != null && Number.isFinite(value));

  const avgResolutionDays = resolutionDays.length
    ? round1(resolutionDays.reduce((sum, value) => sum + value, 0) / resolutionDays.length)
    : 0;

  return {
    snapshot: "current",
    residents_in_window: residentsInWindow,
    check_ins_sent: checkInsSent,
    replies_received: repliesReceived,
    issues_found: issuesFound,
    issues_resolved: issuesResolved.length,
    avg_resolution_days: avgResolutionDays,
    at_risk_count: atRisk.length,
    staying_count: staying.length,
    turnover_exposure: atRisk.length * turnoverCost,
    exposure_recovered: issuesResolved.length * turnoverCost,
    updated_at: new Date().toISOString(),
  };
}

/**
 * Exposure for a cohort before anything has been sent - used in the generation
 * summary card so the prospect sees a number at the very start of the demo.
 */
function windowExposure(leases, cohort, config = {}) {
  const turnoverCost = num(config.avg_turnover_cost, 3900);
  const count = (leases || []).filter((lease) => txt(lease.cohort) === txt(cohort)).length;
  return count * turnoverCost;
}

/** Fields written to the Metrics table (strips the digest-only keys). */
function toMetricsRecord(metrics) {
  return {
    snapshot: metrics.snapshot || "current",
    residents_in_window: metrics.residents_in_window,
    check_ins_sent: metrics.check_ins_sent,
    replies_received: metrics.replies_received,
    issues_found: metrics.issues_found,
    issues_resolved: metrics.issues_resolved,
    avg_resolution_days: metrics.avg_resolution_days,
    at_risk_count: metrics.at_risk_count,
    turnover_exposure: metrics.turnover_exposure,
    exposure_recovered: metrics.exposure_recovered,
    updated_at: metrics.updated_at,
  };
}
/**
 * Telegram card and inline-keyboard builders for the v2 demo.
 *
 * This file is inlined into n8n Code nodes at import time, the same way the v1
 * stage libraries are, so it must stay dependency-free and browser-safe.
 *
 * Telegram constraints enforced here:
 *  - callback_data must be 64 bytes or fewer. Actions use 3-character prefixes
 *    plus an Airtable record id (17 chars), so the longest payload is ~21 bytes.
 *  - message text must be 4096 characters or fewer. Long drafts are truncated
 *    for display only; the stored draft is never shortened.
 *  - only one Telegram Trigger may be active per bot, so every button in this
 *    file is routed through WF6.
 */

const CALLBACK_MAX_BYTES = 64;
const MESSAGE_MAX_CHARS = 4096;

const ACTIONS = {
  APPROVE_SEND: "apv",
  SKIP_DRAFT: "skp",
  NEXT_DRAFT: "nxt",
  DRAFT_ASSIST: "ast",
  SEND_ASSIST: "snd",
  DISCARD_ASSIST: "dis",
  MARK_RESOLVED: "res",
  SEND_CONFIRMATION: "cnf",
  ACK_HANDOFF: "hnd",
  EDIT_DRAFT: "edt",
};

function textOf(value) {
  return value == null ? "" : String(value).trim();
}

function escapeHtml(value) {
  return textOf(value)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;");
}

function truncate(value, limit) {
  const text = textOf(value);
  if (text.length <= limit) return text;
  return `${text.slice(0, Math.max(0, limit - 1))}…`;
}

/** Encodes a button payload and fails loudly rather than letting Telegram reject it. */
function encodeCallback(action, recordId) {
  const payload = `${action}:${textOf(recordId)}`;
  const size = Buffer.byteLength(payload, "utf8");
  if (size > CALLBACK_MAX_BYTES) {
    throw new Error(`callback_data is ${size} bytes, over Telegram's ${CALLBACK_MAX_BYTES}-byte cap: ${payload}`);
  }
  return payload;
}

function decodeCallback(callbackData) {
  const raw = textOf(callbackData);
  const separator = raw.indexOf(":");
  if (separator === -1) return { action: raw, record_id: "" };
  return {
    action: raw.slice(0, separator),
    record_id: raw.slice(separator + 1),
  };
}

function keyboard(rows) {
  return { inline_keyboard: rows.filter((row) => row && row.length) };
}

function button(label, action, recordId) {
  return { text: label, callback_data: encodeCallback(action, recordId) };
}

function formatDate(value) {
  const text = textOf(value);
  if (!text) return "unknown";
  const parsed = new Date(text);
  if (Number.isNaN(parsed.getTime())) return text;
  return parsed.toISOString().slice(0, 10);
}

function formatMoney(value) {
  const amount = Number(value || 0);
  if (!Number.isFinite(amount)) return "$0";
  return `$${Math.round(amount).toLocaleString("en-US")}`;
}

function badgeLine(lease) {
  return [
    textOf(lease.intent),
    textOf(lease.grievance_category) && textOf(lease.grievance_category) !== "NONE"
      ? textOf(lease.grievance_category)
      : "",
    textOf(lease.compliance_flag) && textOf(lease.compliance_flag) !== "NONE"
      ? textOf(lease.compliance_flag)
      : "",
    textOf(lease.urgency),
  ]
    .filter(Boolean)
    .join(" / ");
}

function residentHeader(lease) {
  const days = textOf(lease.days_to_expiry);
  const leaseEnd = formatDate(lease.lease_end_date);
  const tenure = textOf(lease.tenure_months);
  const parts = [`Lease ends ${leaseEnd}`];
  if (days) parts.push(`${days} days out`);
  if (tenure) parts.push(`${tenure} months resident`);
  return parts.join(" · ");
}

/* ------------------------------------------------------------------ cards */

/**
 * Summary posted once per generation run, before the individual draft cards.
 */
function generationSummaryCard(summary) {
  const lines = [
    `<b>${escapeHtml(summary.touch_label || "Check-ins")} drafted</b>`,
    "",
    `${summary.drafted_count} ready for review`,
  ];

  if (summary.review_failed_count) {
    lines.push(`${summary.review_failed_count} need wording (checks failed twice)`);
  }
  if (summary.handoff_count) {
    lines.push(`${summary.handoff_count} flagged for leasing handoff (no resident email)`);
  }
  if (summary.exposure != null) {
    lines.push("", `Turnover exposure in this window: <b>${formatMoney(summary.exposure)}</b>`);
  }

  lines.push("", "Nothing sends until you approve it.");

  return {
    text: lines.join("\n"),
    reply_markup: summary.first_record_id
      ? keyboard([[button("▶️ Review first draft", ACTIONS.NEXT_DRAFT, summary.first_record_id)]])
      : undefined,
  };
}

/**
 * A single draft awaiting approval. This is the core approval moment.
 */
function draftApprovalCard(lease, options = {}) {
  const lines = [
    `<b>${escapeHtml(lease.tenant_name)} · ${escapeHtml(lease.unit)}</b>`,
    residentHeader(lease),
    "",
    `<b>Subject:</b> ${escapeHtml(lease.draft_subject)}`,
    "",
    escapeHtml(truncate(lease.draft_body, 2400)),
  ];

  if (options.position && options.total) {
    lines.push("", `Draft ${options.position} of ${options.total}`);
  }

  const rows = [
    [
      button("✅ Approve & Send", ACTIONS.APPROVE_SEND, lease.record_id),
      button("⏭ Skip", ACTIONS.SKIP_DRAFT, lease.record_id),
    ],
  ];

  if (options.next_record_id) {
    rows.push([button("➡️ Next draft", ACTIONS.NEXT_DRAFT, options.next_record_id)]);
  }

  return { text: truncate(lines.join("\n"), MESSAGE_MAX_CHARS), reply_markup: keyboard(rows) };
}

/**
 * A draft that failed guardrails twice. Deliberately has no approve button.
 */
function reviewFailedCard(lease) {
  return {
    text: [
      `<b>Needs wording · ${escapeHtml(lease.tenant_name)}, ${escapeHtml(lease.unit)}</b>`,
      "",
      `The draft failed the safety checks twice: ${escapeHtml(lease.data_quality || "see workflow log")}`,
      "",
      "No approve button is offered. Write this one yourself.",
    ].join("\n"),
  };
}

/**
 * 30-day cohort handoff. Internal only - never emails the resident.
 */
function leasingHandoffCard(leases) {
  const lines = [
    `<b>Leasing handoff · ${leases.length} residents at 30 days</b>`,
    "",
    "These are inside the renewal-offer window. No resident email is sent from here — this is a handoff to your leasing team.",
    "",
  ];

  leases.slice(0, 15).forEach((lease) => {
    lines.push(`• ${escapeHtml(lease.tenant_name)}, ${escapeHtml(lease.unit)} — ends ${formatDate(lease.lease_end_date)}`);
  });

  return { text: truncate(lines.join("\n"), MESSAGE_MAX_CHARS) };
}

/**
 * A reply that needs a person. Mirrors the v1 alert content and adds actions.
 */
function atRiskAlertCard(lease, options = {}) {
  const complianceFlag = textOf(lease.compliance_flag);
  const isCompliance = complianceFlag && complianceFlag !== "NONE";

  const lines = [
    `<b>AT RISK · ${escapeHtml(lease.tenant_name)}, ${escapeHtml(lease.unit)}</b>`,
    residentHeader(lease),
    "",
    badgeLine(lease),
    "",
    `<i>"${escapeHtml(truncate(lease.reply_text, 1200))}"</i>`,
    "",
    `<b>Action:</b> ${escapeHtml(lease.suggested_action)}`,
    `Confidence: ${escapeHtml(lease.confidence)}`,
  ];

  if (isCompliance) {
    lines.push("", "<b>Nothing has been sent to the resident.</b> Compliance-sensitive: read it yourself before replying.");
  }

  const rows = [];

  // Compliance-sensitive replies get no one-tap assist. A person decides first.
  if (!isCompliance) {
    rows.push([button("✍️ Draft my reply", ACTIONS.DRAFT_ASSIST, lease.record_id)]);
  }
  if (options.allow_resolve !== false) {
    rows.push([button("✅ Mark resolved", ACTIONS.MARK_RESOLVED, lease.record_id)]);
  }

  return {
    text: truncate(lines.join("\n"), MESSAGE_MAX_CHARS),
    reply_markup: rows.length ? keyboard(rows) : undefined,
  };
}

/**
 * A drafted reply to the resident, awaiting explicit approval before it sends.
 */
function assistApprovalCard(lease) {
  return {
    text: truncate(
      [
        `<b>Suggested reply · ${escapeHtml(lease.tenant_name)}, ${escapeHtml(lease.unit)}</b>`,
        "",
        escapeHtml(truncate(lease.assist_draft, 2800)),
        "",
        "This has not been sent. Approve it and it goes to the resident as written.",
      ].join("\n"),
      MESSAGE_MAX_CHARS
    ),
    reply_markup: keyboard([
      [
        button("✅ Send reply", ACTIONS.SEND_ASSIST, lease.record_id),
        button("⏭ Discard", ACTIONS.DISCARD_ASSIST, lease.record_id),
      ],
    ]),
  };
}

/**
 * Confirmation that the issue is closed, plus the optional resident follow-up.
 */
function resolutionCard(lease, options = {}) {
  const lines = [
    `<b>Issue resolved · ${escapeHtml(lease.tenant_name)}, ${escapeHtml(lease.unit)}</b>`,
    "",
  ];

  if (lease.days_to_resolve != null && lease.days_to_resolve !== "") {
    lines.push(`Closed in ${lease.days_to_resolve} days.`);
  }
  if (options.exposure_recovered != null) {
    lines.push(`Turnover exposure recovered: <b>${formatMoney(options.exposure_recovered)}</b>`);
  }

  if (textOf(lease.assist_draft)) {
    lines.push("", "<b>Follow-up ready for the resident:</b>", "", escapeHtml(truncate(lease.assist_draft, 2000)));
    return {
      text: truncate(lines.join("\n"), MESSAGE_MAX_CHARS),
      reply_markup: keyboard([
        [
          button("✅ Send confirmation", ACTIONS.SEND_CONFIRMATION, lease.record_id),
          button("⏭ Skip", ACTIONS.DISCARD_ASSIST, lease.record_id),
        ],
      ]),
    };
  }

  return { text: truncate(lines.join("\n"), MESSAGE_MAX_CHARS) };
}

/**
 * A reply that could not be matched to a resident. Never guesses an owner.
 */
function unmatchedReplyCard(reply) {
  return {
    text: truncate(
      [
        "<b>Unmatched reply</b>",
        "",
        `From: ${escapeHtml(reply.from_email || "unknown sender")}`,
        `Subject: ${escapeHtml(reply.subject || "(none)")}`,
        "",
